const request = $('Mark Imported Webhook').first()?.json ?? $input.first()?.json ?? {};
const body = request.body ?? request;
const headers = request.headers ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const toArray = (value) => Array.isArray(value) ? value : value === null || value === undefined ? [] : [value];
const parseInteger = (value) => {
  const parsed = Number.parseInt(String(value ?? '').trim(), 10);
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
};
const deriveBaseUrl = (headers, fallback) => {
  const forwardedProto = clean(headers['x-forwarded-proto']);
  const forwardedHost = clean(headers['x-forwarded-host']);
  const host = forwardedHost || clean(headers.host);
  const forwardedPort = clean(headers['x-forwarded-port']);
  if (!host) return fallback;
  const proto = forwardedProto || 'http';
  let authority = host;
  if (forwardedPort && !authority.includes(':')) {
    const isDefaultPort = (proto === 'http' && forwardedPort === '80') || (proto === 'https' && forwardedPort === '443');
    if (!isDefaultPort) authority = `${authority}:${forwardedPort}`;
  }
  return `${proto}://${authority}`;
};
const rawItemValues = [...toArray(body.item_id), ...toArray(body.item_ids)];
const itemIds = [];
const seen = new Set();
for (const rawValue of rawItemValues) {
  const parts = String(rawValue ?? '').replace(/\r/g, '').split(/[\n,;]+/);
  for (const part of parts) {
    const parsed = parseInteger(part);
    if (!parsed || seen.has(parsed)) continue;
    seen.add(parsed);
    itemIds.push(parsed);
  }
}
const batchId = parseInteger(body.batch_id ?? body.batchId);
const targetMembership = clean(body.target_membership ?? body.targetMembership);
const n8nBaseUrl = deriveBaseUrl(headers, 'http://n8n:5678');
let errorMessage = '';
if (!batchId) {
  errorMessage = 'Batch ID is required.';
} else if (!targetMembership) {
  errorMessage = 'Target package is required.';
} else if (!itemIds.length) {
  errorMessage = 'Select at least one exported queue row to mark as imported.';
}
return [{ json: { batch_id: batchId, target_membership: targetMembership, item_ids: itemIds, n8n_base_url: n8nBaseUrl, error_message: errorMessage } }];

const request = $('Resolve Imported Request').first()?.json ?? {};
const result = $input.first()?.json ?? {};
const clean = (value) => value === null || value === undefined ? '' : String(value).trim();
const escapeHtml = (value) => clean(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');
const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined || value === '') return fallback;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return fallback; }
  }
  return value;
};
const errorMessage = clean(result.error_message || request.error_message);
const reviewUrl = `${clean(request.n8n_base_url) || 'http://n8n:5678'}/webhook/clubspark-package-import-queue-review?batch_id=${encodeURIComponent(clean(request.batch_id))}&target_membership=${encodeURIComponent(clean(request.target_membership))}&_ts=${Date.now()}`;
const updatedRows = parseMaybe(result.updated_rows, []);
const updatedCount = Number.parseInt(clean(result.updated_count), 10) || 0;
const rowsHtml = Array.isArray(updatedRows) && updatedRows.length
  ? `<ul>${updatedRows.map((row) => `<li>${escapeHtml(clean(row.member) || `Queue row ${clean(row.id)}`)}</li>`).join('')}</ul>`
  : '';
const title = errorMessage ? 'Mark Imported Failed' : 'Queue Rows Marked Imported';
const message = errorMessage || `Marked ${updatedCount} queue row${updatedCount === 1 ? '' : 's'} as imported.`;
const badgeClass = errorMessage ? 'badge error' : 'badge success';
const badgeText = errorMessage ? 'Action needed' : 'Imported';
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeHtml(title)}</title><style>:root{color-scheme:light;--bg:#f7f8fc;--panel:#ffffff;--ink:#2e3d4e;--muted:#6b7785;--line:#e2e8f0;--danger:#b42318;--danger-soft:#fef3f2;--success:#166534;--success-soft:#ecfdf3;--button-soft:#eef2f7}*{box-sizing:border-box}body{margin:0;padding:24px;font-family:Lato,'Helvetica Neue',Arial,sans-serif;color:var(--ink);background:linear-gradient(180deg,#fbfcfe 0%,var(--bg) 100%)}.panel{max-width:820px;margin:0 auto;background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:28px;box-shadow:0 18px 40px rgba(53,72,91,.08)}.badge{display:inline-flex;padding:6px 12px;border-radius:999px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.badge.error{color:var(--danger);background:var(--danger-soft)}.badge.success{color:var(--success);background:var(--success-soft)}h1{margin:16px 0 8px;font-size:32px;line-height:1.1}p,li{color:var(--muted);line-height:1.6;font-size:16px}ul{margin:18px 0 0 20px;padding:0}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:999px;font:inherit;font-weight:700;text-decoration:none;border:1px solid var(--line);background:var(--button-soft);color:var(--ink)}</style></head><body><main class="panel"><span class="${badgeClass}">${escapeHtml(badgeText)}</span><h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p>${rowsHtml}<div class="actions"><a class="button" href="${escapeHtml(reviewUrl)}">Back to Queue Review</a><button type="button" class="button" onclick="window.close()">Close</button></div></main></body></html>`;
return [{ json: { html, response_code: errorMessage ? 400 : 200 } }];
